package org.jsoup.nodes;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Map;
import org.jsoup.SerializationException;
import org.jsoup.helper.Validate;
import org.jsoup.internal.StringUtil;
import org.jsoup.nodes.Attribute;
import org.jsoup.nodes.Attributes;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class Attribute_setValue_TriageGen2Test {

    private Attributes parent;
    private Attribute attribute;
    private Attribute attributeWithParent;

    @Before
    public void setUp() {
        parent = new Attributes();
        attribute = new Attribute("key", "oldValue");
        attributeWithParent = new Attribute("key", "oldValue", parent);
    }

    @Test
    public void testSetValue_NoParent() {
        // Test setting value without a parent
        String oldValue = attribute.setValue("newValue");
        assertEquals("oldValue", oldValue);
        assertEquals("newValue", attribute.getValue());
    }










}

